import { useForm } from './useForm';

function LoginForm() {
  const { values, handleChange, reset } = useForm({
    email: '',
    password: '',
  });

  return (
    <form>
      <input
        name="email"
        value={values.email}
        onChange={handleChange}
        placeholder="Email"
      />

      <input
        name="password"
        type="password"
        value={values.password}
        onChange={handleChange}
        placeholder="Password"
      />

      <button type="button" onClick={reset}>
        Reset
      </button>
    </form>
  );
}

